using AzdoQualityMetrics.Export;
using AzdoQualityMetrics.Interfaces;
using AzdoQualityMetrics.Models;
using AzdoQualityMetrics.Services;
using AzdoQualityMetrics.Logging;
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;
using Microsoft.Extensions.Logging;
using Avalonia.Controls;
using Avalonia.Platform.Storage;
using System.Collections.ObjectModel;
using System.Diagnostics;

namespace AzdoQualityMetrics.ViewModels;
public partial class MainWindowViewModel : ObservableObject
{
 private readonly IAzureDevOpsClient _api; private readonly IConfigurationService _config; private readonly KpiCalculationService _kpi; private readonly DateRangeCalculationService _dates; private readonly DeliveryQualificationService _qualification; private readonly CsvExportService _csv; private readonly ILogger<MainWindowViewModel> _logger; private CancellationTokenSource? _cts; private Window? _window;
 public ObservableCollection<AreaNode> Areas {get;}=new(); public ObservableCollection<string> WorkItemTypes {get;}=new(); public ObservableCollection<string> CompletedStates {get;}=new(); public ObservableCollection<SelectableOption> WorkItemTypeOptions {get;}=new(); public ObservableCollection<SelectableOption> CompletedStateOptions {get;}=new(); public Array QualificationModes {get;}=Enum.GetValues(typeof(DeliveryQualificationMode)); public Array PeriodUnits {get;}=Enum.GetValues(typeof(PeriodUnit)); public string[] LogFilters {get;}={"All","Information","Warning","Error","Debug"}; public ObservableCollection<WorkItemRecord> Bugs {get;}=new(); public ObservableCollection<WorkItemRecord> Delivered {get;}=new(); public ObservableCollection<UiLogEntry> Logs {get;}=new();
 [ObservableProperty] private string organization=""; [ObservableProperty] private string project=""; [ObservableProperty] private string connectionStatus="Not connected"; [ObservableProperty] private string operation="Ready"; [ObservableProperty] private double progress; [ObservableProperty] private bool isBusy; [ObservableProperty] private DateTime startDate=DateTime.Today.AddDays(-55); [ObservableProperty] private DateTime endDate=DateTime.Today; [ObservableProperty] private int periodValue=8; [ObservableProperty] private PeriodUnit periodUnit=PeriodUnit.Weeks; [ObservableProperty] private DeliveryQualificationMode qualificationMode=DeliveryQualificationMode.LastDoneTransitionInPeriod; [ObservableProperty] private int registeredBugs; [ObservableProperty] private double deliveredEffort; [ObservableProperty] private int deliveredWorkItems; [ObservableProperty] private double bugsPer100Effort; [ObservableProperty] private string metadata="No calculation performed"; [ObservableProperty] private string bugSearch=""; [ObservableProperty] private string deliveredSearch=""; [ObservableProperty] private string logFilter="All";
 public IEnumerable<WorkItemRecord> FilteredBugs=>Bugs.Where(x=>string.IsNullOrWhiteSpace(BugSearch)||$"{x.Id} {x.Title} {x.AreaPath}".Contains(BugSearch,StringComparison.OrdinalIgnoreCase)); public IEnumerable<WorkItemRecord> FilteredDelivered=>Delivered.Where(x=>string.IsNullOrWhiteSpace(DeliveredSearch)||$"{x.Id} {x.Title} {x.WorkItemType}".Contains(DeliveredSearch,StringComparison.OrdinalIgnoreCase)); public IEnumerable<UiLogEntry> FilteredLogs=>Logs.Where(x=>LogFilter=="All"||x.Level.Equals(LogFilter,StringComparison.OrdinalIgnoreCase));
 public MainWindowViewModel(IAzureDevOpsClient api,IConfigurationService config,KpiCalculationService kpi,DateRangeCalculationService dates,DeliveryQualificationService qualification,CsvExportService csv,ILogger<MainWindowViewModel> logger){_api=api;_config=config;_kpi=kpi;_dates=dates;_qualification=qualification;_csv=csv;_logger=logger;Organization=config.Settings.Organization;Project=config.Settings.Project;AddLog("Information","Application started");AddLog("Information","Configuration loaded");}
 public void Attach(Window window)=>_window=window;
 partial void OnBugSearchChanged(string value)=>OnPropertyChanged(nameof(FilteredBugs)); partial void OnDeliveredSearchChanged(string value)=>OnPropertyChanged(nameof(FilteredDelivered)); partial void OnLogFilterChanged(string value)=>OnPropertyChanged(nameof(FilteredLogs));
 partial void OnEndDateChanged(DateTime value){if(value.Date>=StartDate.Date)PeriodValue=_dates.PeriodValue(StartDate,value,PeriodUnit);}
 partial void OnStartDateChanged(DateTime value){if(value.Date<=EndDate.Date)PeriodValue=_dates.PeriodValue(value,EndDate,PeriodUnit);}
 partial void OnPeriodValueChanged(int value){if(value>0){var range=_dates.FromPeriod(EndDate,value,PeriodUnit);StartDate=range.Start;}}
 partial void OnPeriodUnitChanged(PeriodUnit value){if(PeriodValue>0){var range=_dates.FromPeriod(EndDate,PeriodValue,value);StartDate=range.Start;}}
 [RelayCommand] private async Task ConnectAsync(){await RunAsync("Connecting…",async ct=>{await _config.SaveConnectionAsync(Organization,Project,ct);await _api.ConnectAsync(ct);ConnectionStatus="Connected";AddLog("Information","Connected to Azure DevOps");});}
 [RelayCommand] private async Task RefreshAreasAsync(){await RunAsync("Loading areas…",async ct=>{Areas.Clear();foreach(var a in await _api.GetAreasAsync(ct))Areas.Add(a);AddLog("Information",$"Loaded {Areas.Count} area roots");});}
 [RelayCommand] private async Task RefreshTypesAsync(){await RunAsync("Loading work item types…",async ct=>{WorkItemTypes.Clear();WorkItemTypeOptions.Clear();foreach(var t in await _api.GetWorkItemTypesAsync(ct)){WorkItemTypes.Add(t.Name);WorkItemTypeOptions.Add(new SelectableOption(t.Name,t.Name is "Product Backlog Item" or "User Story"));}AddLog("Information",$"Loaded {WorkItemTypes.Count} work item types");});}
 [RelayCommand] private async Task RefreshStatesAsync(){await RunAsync("Loading states…",async ct=>{CompletedStates.Clear();CompletedStateOptions.Clear();foreach(var state in (await _api.GetStatesAsync(ct)).Where(x=>x.Category=="Completed").Select(x=>x.Name).Distinct()){CompletedStates.Add(state);CompletedStateOptions.Add(new SelectableOption(state,true));}AddLog("Information",$"Loaded {CompletedStates.Count} completed states");});}
 [RelayCommand] private async Task GoAsync(){await RunAsync("Calculating KPI…",async ct=>{var sw=Stopwatch.StartNew();var areas=FlattenSelected(Areas).ToList();var selectedTypes=WorkItemTypeOptions.Where(x=>x.IsSelected).Select(x=>x.Name).ToList();var selectedStates=CompletedStateOptions.Where(x=>x.IsSelected).Select(x=>x.Name).ToList();var req=new CalculationRequest(StartDate.Date,EndDate.Date,areas,selectedTypes,selectedStates,QualificationMode);AddLog("Information","KPI calculation started");var bugIds=await _api.QueryWorkItemIdsAsync(req,true,ct);var deliveryIds=await _api.QueryWorkItemIdsAsync(req,false,ct);var bugRows=await _api.GetWorkItemsAsync(bugIds,ct);var deliveryRows=await _api.GetWorkItemsAsync(deliveryIds,ct);Bugs.Clear();foreach(var b in bugRows.Where(x=>x.CreatedDate?.Date>=StartDate.Date&&x.CreatedDate?.Date<=EndDate.Date))Bugs.Add(b);Delivered.Clear();var i=0;foreach(var item in deliveryRows){ct.ThrowIfCancellationRequested();i++;Operation=$"Processing item {i} of {deliveryRows.Count}…";var updates=await _api.GetUpdatesAsync(item.Id,ct);if(_qualification.Qualifies(updates,StartDate,EndDate,selectedStates,QualificationMode,out var done)){if(item.Effort is null){AddLog("Warning",$"Work item {item.Id} missing Effort field");continue;}item.DoneDate=done;item.QualificationMode=QualificationMode.ToString();Delivered.Add(item);}Progress=deliveryRows.Count==0?100:(double)i/deliveryRows.Count*100;}var result=_kpi.Calculate(Bugs,Delivered);RegisteredBugs=result.Bugs;DeliveredEffort=result.Effort;DeliveredWorkItems=result.DeliveredWorkItems;BugsPer100Effort=result.BugsPer100Effort;sw.Stop();Metadata=$"Areas: {areas.Count} | States: {selectedStates.Count} | Mode: {QualificationMode} | Duration: {sw.Elapsed.TotalSeconds:0.0}s | Retrieved: {bugIds.Count+deliveryIds.Count}";AddLog("Information",$"Calculation completed. KPI = {BugsPer100Effort:0.00}");OnPropertyChanged(nameof(FilteredBugs));OnPropertyChanged(nameof(FilteredDelivered));});}
 [RelayCommand] private void Cancel(){_cts?.Cancel();Operation="Cancelling…";}
 [RelayCommand] private async Task ExportBugsAsync()=>await ExportAsync("Export registered bugs",(p,ct)=>_csv.ExportBugsAsync(p,Bugs,ct),"bugs.csv");
 [RelayCommand] private async Task ExportDeliveredAsync()=>await ExportAsync("Export delivered work",(p,ct)=>_csv.ExportDeliveredAsync(p,Delivered,ct),"delivered-work.csv");
 [RelayCommand] private async Task ExportKpiAsync()=>await ExportAsync("Export KPI summary",(p,ct)=>_csv.ExportKpiAsync(p,new KpiResult(RegisteredBugs,DeliveredEffort,DeliveredWorkItems,BugsPer100Effort),ct),"kpi-summary.csv");
 private async Task ExportAsync(string title,Func<string,CancellationToken,Task> action,string name){if(_window is null)return;var file=await _window.StorageProvider.SaveFilePickerAsync(new FilePickerSaveOptions{Title=title,SuggestedFileName=name,FileTypeChoices=new[]{new FilePickerFileType("CSV") {Patterns=new[]{"*.csv"}}}});if(file is not null)await action(file.Path.LocalPath,CancellationToken.None);}
 [RelayCommand] private async Task OpenLogFolderAsync(){var path=Path.Combine(AppContext.BaseDirectory,"logs");Directory.CreateDirectory(path);try{Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}catch(Exception ex){AddLog("Error",ex.Message);}}
 private async Task RunAsync(string label,Func<CancellationToken,Task> action){if(IsBusy)return;_cts=new CancellationTokenSource();IsBusy=true;Progress=0;Operation=label;try{await action(_cts.Token);Operation="Ready";}catch(OperationCanceledException){Operation="Cancelled";AddLog("Warning","Operation cancelled by user");}catch(Exception ex){_logger.LogError(ex,"Operation failed");AddLog("Error",ex.Message);Operation="Operation failed";ConnectionStatus="Error";}finally{IsBusy=false;_cts.Dispose();_cts=null;}}
 private static IEnumerable<string> FlattenSelected(IEnumerable<AreaNode> nodes){foreach(var n in nodes){if(n.IsSelected){yield return n.Path;continue;}foreach(var p in FlattenSelected(n.Children))yield return p;}}
 private void AddLog(string level,string message){Logs.Add(new UiLogEntry(DateTime.Now,level,message));if(level=="Error")_logger.LogError("{Message}",message);else if(level=="Warning")_logger.LogWarning("{Message}",message);else _logger.LogInformation("{Message}",message);OnPropertyChanged(nameof(FilteredLogs));}
}
